/*
      * 阅读区域总宽度，包含正文两侧内边距。
      * 可以改成 900px、960px、1050px。
      */
.Post-content {
    --reading-width: 1000px;
}

/* 1. 双栏容器改成单栏，并在页面中居中 */
.Post-content .css-kjzwqj {
    display: block !important;
    width: calc(100% - 32px) !important;
    max-width: var(--reading-width) !important;
    min-width: 0 !important;
    margin-inline: auto !important;
    box-sizing: border-box !important;
}

/* 2. 隐藏整个右栏：侧栏作者卡与热榜
           标题下方的作者信息不在这里，不会被隐藏 */
.Post-content .css-kjzwqj > .css-1ni4jcm {
    display: none !important;
}

/* 3. 放开正文外面两层原本约 694px 的容器 */
.Post-content .css-kjzwqj > .css-c0fani,
.Post-content .css-kjzwqj > .css-c0fani > .css-yq5nsh {
    width: 100% !important;
    max-width: none !important;
    min-width: 0 !important;
    box-sizing: border-box !important;
}

/* 4. 正文跟随父容器加宽，不再固定在约 654px */
.Post-content .Post-Main,
.Post-content .Post-RichTextContainer,
.Post-content .Post-RichTextContainer > .css-1od93p9,
.Post-content .Post-RichText {
    width: 100% !important;
    max-width: none !important;
    min-width: 0 !important;
    box-sizing: border-box !important;
}

.Post-content .Post-Main {
    margin-inline: auto !important;
}

/* 阅读区域从 1000px 加宽到 1100px */
.Post-content {
    --reading-width: 1100px;
}

/* 仅隐藏看山入口，保留返回顶部等其他按钮 */
.CornerButtons--kanshan,
.CornerAnimayedFlex--kanshan,
.KanshanCornerButton {
    display: none !important;
}

/* 隐藏搜索框旁的直答入口 */
.AppHeader .SearchBar > a.css-so42cc {
    display: none !important;
}

/* 顶部：AI Works */
.AppHeader nav a[href="https://www.zhihu.com/project-square"] {
    display: none !important;
}

/* 顶部：故事 */
.AppHeader nav a[href="https://www.zhihu.com/fiore/h5/vip-web"] {
    display: none !important;
}

/* 文章操作栏：解释这篇内容 */
.Post-Main .ContentItem-actions button[data-tooltip="解释这篇内容"] {
    display: none !important;
}

/* 搜索栏与右侧 + 按钮之间留白 */
.AppHeader .SearchBar {
    margin-inline-end: 16px !important;
}

/* 撤销上次没有达到预期效果的外边距 */
.AppHeader .SearchBar {
    margin-inline-end: 0 !important;
}

/* 在搜索区域内部的横向子元素之间留白 */
.AppHeader .SearchBar,
.AppHeader .css-x84wzl {
    column-gap: 16px !important;
}

/* 搜索框填满可用空间，不再限宽并靠右 */
.AppHeader .SearchBar-input {
    width: 100% !important;
    max-width: none !important;
    min-width: 0 !important;
    margin-inline: 0 !important;
    box-sizing: border-box !important;
}

/* 搜索区域与左侧导航分隔线留出间隔 */
.AppHeader .css-x84wzl {
    padding-inline-start: 16px !important;
    min-width: 0 !important;
    box-sizing: border-box !important;
}

/* 窄窗口下允许搜索框收缩 */
.AppHeader .SearchBar,
.AppHeader .SearchBar-tool {
    min-width: 0 !important;
}

/* 扩大整体阅读区域 */
.Post-content {
    --reading-width: 1200px;
}

/* 增加白色正文容器的左右内边距 */
.Post-content .css-kjzwqj > .css-c0fani > .css-yq5nsh {
    padding-inline: clamp(24px, 5vw, 64px) !important;
    box-sizing: border-box !important;
}

/* 目录宽 76px，再与正文保持 16px 间隔 */
.Post-content .css-1kerlqf:has(.Catalog) {
    left: -92px !important;
    right: auto !important;
    width: 76px !important;
}

/* 整块正文卡片的轻阴影 */
     .Post-content .css-kjzwqj > .css-c0fani > .css-yq5nsh {
       box-shadow: 0 1px 6px rgba(18, 18, 18, 0.10) !important;
     }

/* 顶部导航：AI Works、故事 */
     .AppHeader nav a[href="https://www.zhihu.com/project-square"],
     .AppHeader nav a[href="/project-square"],
     .AppHeader nav a[href="https://www.zhihu.com/fiore/h5/vip-web"],
     .AppHeader nav a[href="/fiore/h5/vip-web"] {
       display: none !important;
     }

     /* 搜索框旁的直答 */
     .AppHeader .SearchBar > a.css-so42cc {
       display: none !important;
     }

     /* 看山入口 */
     .CornerButtons--kanshan,
     .CornerAnimayedFlex--kanshan,
     .KanshanCornerButton {
       display: none !important;
     }

     /* 搜索框填满可用宽度 */
     .AppHeader .SearchBar-input {
       width: 100% !important;
       max-width: none !important;
       min-width: 0 !important;
       margin-inline: 0 !important;
       box-sizing: border-box !important;
     }

     /* 搜索框与右侧按钮的间隔 */
     .AppHeader .SearchBar {
       margin-inline-end: 0 !important;
       min-width: 0 !important;
       column-gap: 16px !important;
     }

     /* 搜索区域与左侧导航的间隔 */
     .AppHeader .css-x84wzl {
       padding-inline-start: 16px !important;
       min-width: 0 !important;
       column-gap: 16px !important;
       box-sizing: border-box !important;
     }

     .AppHeader .SearchBar-tool {
       min-width: 0 !important;
     }

     /* 内容操作栏：解释入口 */
     .ContentItem-actions button[data-tooltip="解释这篇内容"] {
       display: none !important;
     }
